import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    registered = [int(v) for v in data[1:1 + n]]
    q = int(data[1 + n])
    queries = [int(v) for v in data[2 + n:2 + n + q]]
    for x in queries:
        count = 0
        for v in registered:
            if v == x:
                count += 1
        if count > 0:
            print("YES")
        else:
            print("NO")


main()
